var dateColumn = "'D_Calendar'[Calendar Date]";

// Creates time intelligence measures for every selected measure:
foreach (var m in Selected.Measures)
{
    // Previous year:
    m.Table.AddMeasure(
        m.Name + " PY", 
        "CALCULATE(" + m.DaxObjectName + ", SAMEPERIODLASTYEAR(" + dateColumn + "))", 
        m.DisplayFolder + "\\Labels\\TI"
    );

    // YoY:
    m.Table.AddMeasure(
        m.Name + " YoY", 
        m.DaxObjectName + " - [" + m.Name + " PY]", 
        m.DisplayFolder + "\\Labels\\TI"
    );

    // YoY%:
    m.Table.AddMeasure(
        m.Name + " YoY%", 
        "DIVIDE([" + m.Name + " YoY], [" + m.Name + " PY], 0)", 
        m.DisplayFolder + "\\Labels\\TI"
    );

    // Year-to-date:
    m.Table.AddMeasure(
        m.Name + " YTD", 
        "VAR _Count = COUNTROWS('F_EmployeeTimesheet') " +
        "RETURN " +
        "IF(" +
            "ISBLANK(_Count), " +
            "BLANK(), " +
            "CALCULATE(" + m.DaxObjectName + ", DATESYTD(" + dateColumn + "))" +
        ")", 
        m.DisplayFolder + "\\Labels\\TI"
    );

    // PYTD:
    m.Table.AddMeasure(
        m.Name + " YTD PY", 
        "VAR _Count = COUNTROWS('F_EmployeeTimesheet') " +
        "RETURN " +
        "IF(" +
            "ISBLANK(_Count), " +
            "BLANK(), " +
            "CALCULATE(" + m.DaxObjectName + ", DATESYTD(SAMEPERIODLASTYEAR(" + dateColumn + ")))" +
        ")", 
        m.DisplayFolder + "\\Labels\\TI"
    );

    // YTD label:
    var ytdMeasure = "[" + m.Name + " YTD]";
    var pytdMeasure = "[" + m.Name + " YTD PY]";
    var ytdDeltaMeasure = "[" + m.Name + " YTD YoY]";
    var ytdDeltaPPMeasure = "[" + m.Name + " YTD YoY%]";

    // YoY for YTD:
    m.Table.AddMeasure(
        m.Name + " YTD YoY", 
        ytdMeasure + " - " + pytdMeasure, 
        m.DisplayFolder + "\\Labels\\TI"
    );

    // YoY% for YTD:
    m.Table.AddMeasure(
        m.Name + " YTD YoY%", 
        "DIVIDE(" + ytdDeltaMeasure + ", " + pytdMeasure + ", 0)", 
        m.DisplayFolder + "\\Labels\\TI"
    );

    // Label for YTD:
    var ytdArrowExpression = "IF(" + ytdDeltaMeasure + " < 0, UNICHAR(128317), UNICHAR(128316))";
    var ytdLabelExpression = 
        "" + ytdArrowExpression + " & \" \" & " +
        "FORMAT(" + ytdDeltaPPMeasure + ", \"+ 0.00%;- 0.00%;0.00%\")";

    m.Table.AddMeasure(
        m.Name + " YTD label", 
        ytdLabelExpression, 
        m.DisplayFolder + "\\Labels"
    );

    // Label measure:
    var deltaMeasure = "[" + m.Name + " YoY]";
    var deltaPPMeasure = "[" + m.Name + " YoY%]";
    var arrowExpression = "IF(" + deltaMeasure + " < 0, UNICHAR(128317), UNICHAR(128316))";
    var labelExpression = 
        "" + arrowExpression + " & \" \" & " +
        "FORMAT(" + deltaPPMeasure + ", \"+ 0.00%;- 0.00%;0.00%\")";

    m.Table.AddMeasure(
        m.Name + " label", 
        labelExpression, 
        m.DisplayFolder + "\\Labels"
    );
}

// This script is meant to format all measures with a default formatstring
foreach (var ms in Selected.Measures) {
//Don't set format string on hidden measures
	if (ms.IsHidden) continue;
// If the format string is empty continue. 
	if (!string.IsNullOrWhiteSpace(ms.FormatString)) continue;
//If the data type is int set a whole number format string
	if (ms.DataType == DataType.Int64) ms.FormatString = "#,##0";
//If the datatype is double or decimal 
	if (ms.DataType == DataType.Double || ms.DataType == DataType.Decimal) {
    //and the name contains # or QTY then set the format string to a whole number
		if (ms.Name.Contains("#")
			|| ms.Name.IndexOf("QTY", StringComparison.OrdinalIgnoreCase) >= 0) ms.FormatString = "#,##0";
		//otherwise set it a decimal format string. 
    else ms.FormatString = "#,##0.00";
	}
}

// This script will automatically generate an Incremental Refresh policy for a selected table
// It is generated based on the selected column
// It requires input from the user with a dialogue pop-up box.
using System.Drawing;
using System.Windows.Forms;

// Hide the 'Running Macro' spinbox
ScriptHelper.WaitFormVisible = false;

// Initialize Variables
Table _Table                = Model.Tables[0];
string _MExpression         = "";
Column _Column              = Model.AllColumns.ToList()[0];
string _ColumnName          = "";
DataType _ColumnDataType    = DataType.DateTime;

try
    {   
        // Select a Table for which you will configure Incremental Refresh.
        // The Refresh Policy will be enabled and configured for this table.
        _Table = 
            Model.Tables.Where(

                // Exclude tables that already have a refresh policy
                t => 
                t.EnableRefreshPolicy != true && 

                // Include only 'Table' objects
                t.ObjectType == ObjectType.Table && 

                // Exclude Calculated Tables
                t.Columns[0].Type != ColumnType.CalculatedTableColumn && 

                // Exclude tables that have columns on the 'From' end of a Relationship
                t.Columns.Any(c => Model.Relationships.Any(r => r.FromColumn == c) ) && 

                // Exclude tables that don't have a DateTime or Integer column
                (
                    t.Columns.Any(c => c.DataType == DataType.DateTime) || 
                    t.Columns.Any(c => c.DataType == DataType.Int64)
                )
            ).SelectTable(null,"Select a Table for which you will configure Incremental Refresh:");

        _MExpression = _Table.Partitions[0].Expression;

    try
    {
        // Select the column to apply the Refresh Policy. 
        // The M Expression will be modified using the name of this column.
        _Column = 
            _Table.Columns.Where(

                // Include only DateTime or Int columns
                c => 
                c.DataType == DataType.DateTime || 
                c.DataType == DataType.Int64

            ).SelectColumn(null, "Select a DateTime or DateKey (Int) Column to apply the Refresh Policy.");

        _ColumnName = _Column.DaxObjectName;
        _ColumnDataType = _Column.DataType;

        try 
        {   // Test if 'RangeStart' exists
            Model.Expressions.Contains(Model.Expressions["RangeStart"]);
            Info ("RangeStart already exists!");
        }
        catch
        {
            // Add RangeStart parameter
            Model.AddExpression( 
                "RangeStart", 
                @"
            #datetime(2023, 01, 01, 0, 0, 0) meta
            [
                IsParameterQuery = true,
                IsParameterQueryRequired = true,
                Type = type datetime
            ]"
            );

            // Success message for adding 'RangeStart'
            Info ( "Created 'RangeStart' M Parameter!" );
        }

        // Test if the RangeEnd parameter exists
        try 
        {   // Test if 'RangeEnd' exists
            Model.Expressions.Contains(Model.Expressions["RangeEnd"]);
            Info ("RangeEnd already exists!");
        }
        catch
        {
            // Add RangeEnd parameter
            Model.AddExpression( 
                "RangeEnd", 
                @"
            #datetime(2023, 31, 01, 0, 0, 0) meta
            [
                IsParameterQuery = true,
                IsParameterQueryRequired = true,
                Type = type datetime
            ]"
            );

            // Success message for adding 'RangeEnd'
            Info ( "Created 'RangeEnd' M Parameter!" );

        }

        // Incremental Refresh Configuration
        // Input box config
        Font _fontConfig = new Font("Segoe UI", 11);

        // Label for how long data should be stored
        var storeDataLabel = new Label();
        storeDataLabel.Text = "Store data in the last:";
        storeDataLabel.Location = new Point(20, 20);
        storeDataLabel.AutoSize = true;
        storeDataLabel.Font = _fontConfig;

        // User input for how long data should be stored
        var storeDataTextBox = new TextBox();
        storeDataTextBox.Location = new Point(storeDataLabel.Location.X + TextRenderer.MeasureText(storeDataLabel.Text, storeDataLabel.Font).Width + 20, storeDataLabel.Location.Y);
        storeDataTextBox.Size = new Size(100, 20);
        storeDataTextBox.Text = "3";
        storeDataTextBox.Font = _fontConfig;

        // User selection for how long data should be stored (granularity)
        var storeDataComboBox = new ComboBox();
        storeDataComboBox.Location = new Point(storeDataTextBox.Location.X + storeDataTextBox.Width + 20, storeDataLabel.Location.Y);
        storeDataComboBox.Size = new Size(100, 20);
        storeDataComboBox.DropDownStyle = ComboBoxStyle.DropDownList;
        storeDataComboBox.Items.AddRange(new object[] { "days", "months", "quarters", "years" });
        storeDataComboBox.SelectedIndex = 3;
        storeDataComboBox.Font = _fontConfig;

        // Label for how much data should be refreshed
        var refreshDataLabel = new Label();
        refreshDataLabel.Text = "Refresh data in the last:";
        refreshDataLabel.Location = new Point(20, storeDataLabel.Location.Y + storeDataLabel.Height + 15);
        refreshDataLabel.AutoSize = true;
        refreshDataLabel.Font = _fontConfig;

        // User input for how much data should be refreshed
        var refreshDataTextBox = new TextBox();
        refreshDataTextBox.Location = new Point(storeDataTextBox.Location.X, refreshDataLabel.Location.Y);
        refreshDataTextBox.Size = new Size(100, 20);
        refreshDataTextBox.Text = "30";
        refreshDataTextBox.Font = _fontConfig;

        // User selection for how much data should be refreshed (Period)
        var refreshDataComboBox = new ComboBox();
        refreshDataComboBox.Location = new Point(storeDataComboBox.Location.X, refreshDataLabel.Location.Y);
        refreshDataComboBox.Size = new Size(100, 20);
        refreshDataComboBox.DropDownStyle = ComboBoxStyle.DropDownList;
        refreshDataComboBox.Items.AddRange(new object[] { "days", "months", "quarters", "years" });
        refreshDataComboBox.SelectedIndex = 0;
        refreshDataComboBox.Font = _fontConfig;

        // User input to refresh full periods or not
        var fullPeriodsCheckBox = new CheckBox();
        fullPeriodsCheckBox.Text = "Refresh only full periods";
        fullPeriodsCheckBox.Location = new Point(storeDataLabel.Location.X + 3, refreshDataLabel.Location.Y + refreshDataLabel.Height + 15);
        fullPeriodsCheckBox.AutoSize = true;
        fullPeriodsCheckBox.Font = _fontConfig;

        // Form OK button
        var okButton = new Button();
        okButton.Text = "OK";
        okButton.Location = new Point(storeDataLabel.Location.X, fullPeriodsCheckBox.Location.Y + fullPeriodsCheckBox.Height + 15);
        okButton.MinimumSize = new Size(80, 25);
        okButton.AutoSize = true;
        okButton.DialogResult = DialogResult.OK;
        okButton.Font = _fontConfig;

        // Form cancel button
        var cancelButton = new Button();
        cancelButton.Text = "Cancel";
        cancelButton.Location = new Point(okButton.Location.X + okButton.Width + 10, okButton.Location.Y);
        cancelButton.MinimumSize = new Size(80, 25);
        cancelButton.AutoSize = true;
        cancelButton.DialogResult = DialogResult.Cancel;
        cancelButton.Font = _fontConfig;

        // Adjust the Location of the storeDataLabel to align with the storeDataTextBox
        storeDataLabel.Location = new Point(storeDataLabel.Location.X, storeDataLabel.Location.Y + 4);
        refreshDataLabel.Location = new Point(refreshDataLabel.Location.X, refreshDataLabel.Location.Y + 4);

        // Form config
        var form = new Form();
        form.Text = "Incremental Refresh configuration:";
        form.AutoSize = true;
        form.MinimumSize = new Size(450, 0);
        form.FormBorderStyle = FormBorderStyle.FixedDialog;
        form.MaximizeBox = false;
        form.MinimizeBox = false;

        // Open the dialogue in the center of the screen
        form.StartPosition = FormStartPosition.CenterScreen;

        // Set the AutoScaleMode property to Dpi
        form.AutoScaleMode = AutoScaleMode.Dpi;

        // Add controls to form specified above
        form.Controls.Add(storeDataLabel);
        form.Controls.Add(storeDataTextBox);
        form.Controls.Add(storeDataComboBox);
        form.Controls.Add(refreshDataLabel);
        form.Controls.Add(refreshDataTextBox);
        form.Controls.Add(refreshDataComboBox);
        form.Controls.Add(fullPeriodsCheckBox);
        form.Controls.Add(okButton);
        form.Controls.Add(cancelButton);

        // Draw the form
        var result = form.ShowDialog();

        // Get the values of the user input if entered
        if (result == DialogResult.OK)
        {
            // Enables the refresh policy
            _Table.EnableRefreshPolicy = true;

            var storeDataValue = storeDataTextBox.Text;
            var storeDataComboBoxValue = storeDataComboBox.SelectedItem.ToString();
            var refreshDataValue = refreshDataTextBox.Text;
            var refreshDataComboBoxValue = refreshDataComboBox.SelectedItem.ToString();
            var fullPeriodsChecked = fullPeriodsCheckBox.Checked;

            // Display the input values in a message box
            var message = string.Format(
                "Store data in the last: {0} {1}" + 
                "\nRefresh data in the last: {2} {3}" + 
                "\nRefresh only full periods: {4}",
                storeDataTextBox.Text,
                storeDataComboBox.SelectedItem.ToString(),
                refreshDataTextBox.Text,
                refreshDataComboBox.SelectedItem.ToString(),
                fullPeriodsCheckBox.Checked);

            Info(message);

            // Convert StoreDataGranularity to correct TOM Property
            RefreshGranularityType StoreDataGranularity = RefreshGranularityType.Day;
            switch (storeDataComboBox.SelectedItem.ToString())
            {
                case "years":
                    StoreDataGranularity = RefreshGranularityType.Year;
                    break;

                case "quarters":
                    StoreDataGranularity = RefreshGranularityType.Quarter;
                    break;

                case "months":
                    StoreDataGranularity = RefreshGranularityType.Month;
                    break;

                case "days":
                    StoreDataGranularity = RefreshGranularityType.Day;
                    break; 

                default:
                    Error("Bad selection for Incremental Granularity.");
                    break;
            }


            // Convert IncrementalGranularity to correct TOM Property
            RefreshGranularityType IncrementalPeriodGranularity = RefreshGranularityType.Year;
            switch (refreshDataComboBox.SelectedItem.ToString())
            {
                case "years":
                    IncrementalPeriodGranularity = RefreshGranularityType.Year;
                    break;

                case "quarters":
                    IncrementalPeriodGranularity = RefreshGranularityType.Quarter;
                    break;

                case "months":
                    IncrementalPeriodGranularity = RefreshGranularityType.Month;
                    break;

                case "days":
                    IncrementalPeriodGranularity = RefreshGranularityType.Day;
                    break; 

                default:
                    Error ( "Bad selection for Incremental Granularity." );
                    break;
            }

            // Convert RefreshCompletePeriods checkbox to correct TOM property
            int RefreshCompletePeriods;
            if ( fullPeriodsCheckBox.Checked == true )
            { 
            RefreshCompletePeriods = -1;
            }
            else
            {
            RefreshCompletePeriods = 0;
            }

            // Set incremental window: period to be refreshed
            _Table.IncrementalGranularity = IncrementalPeriodGranularity;

            // Default: 30 days - change # if you want
            _Table.IncrementalPeriods = Convert.ToInt16(refreshDataTextBox.Text);

            // Only refresh complete days. Change to 0 if you don't want.
            _Table.IncrementalPeriodsOffset = RefreshCompletePeriods;

            // Set rolling window: period to be archived
            // Granularity = day, can change to month, quarter, year...
            _Table.RollingWindowGranularity = StoreDataGranularity;

            // Keep data for 1 year. Includes 1 full year and current partial year 
            //    i.e. if it is Nov 2023, keeps data from Jan 1, 2022. 
            //    On Jan 1, 2024, it will drop 2022 automatically.
            _Table.RollingWindowPeriods = Convert.ToInt16(storeDataTextBox.Text);

            // If the selected date column is an integer of type YYYYMMDD...
            if ( _ColumnDataType == DataType.Int64 )
            {
                // Add DateTimeToInt Function
                var _DateTimeToInt = 
                    Model.AddExpression( 
                        "fxDateTimeToInt", 
                        @"(x as datetime) => Date.Year(x) * 10000 + Date.Month(x) * 100 + Date.Day(x)"
            );

            _DateTimeToInt.SetAnnotation("PBI_ResultType", "Function");
            _DateTimeToInt.Kind = ExpressionKind.M;

            // Source expression obtained from the original M partition
            _Table.SourceExpression = 

                // Gets expression before final "in" keyword
                _MExpression.Split("\nin")[0].TrimEnd() +

                // Adds comma and newline
                ",\n" +

                // Adds step called "Incremental Refresh" for filtering
                @"    #""Incremental Refresh"" = Table.SelectRows( " +

                // Gets name of last step (after "in" keyword)
                _MExpression.Split("\nin")[1].TrimStart() +

                // Adds 'each' keyword
                @", each " +

                // Bases incremental refresh on current column name
                _ColumnName +

                // Greater than or equal to RangeStart
                @" >= fxDateTimeToInt ( #""RangeStart"" ) and " +

                // and
                _ColumnName +

                // Less than RangeEnd
                @" < fxDateTimeToInt ( #""RangeEnd"" ) )" +

                // re-add 'in' keyword
                "\nin\n" +

                // Reference final step just added
                @"    #""Incremental Refresh""";
            }


            // Otherwise treat it like a normal date/datetime column
            else
            {
                // Source expression obtained from the original M partition
                _Table.SourceExpression = 
                    // Gets expression before final "in" keyword
                    _MExpression.Split("\nin")[0].TrimEnd() +

                    // Adds comma and newline
                    ",\n" +

                    // Adds step called "Incremental Refresh" for filtering
                    @"    #""Incremental Refresh"" = Table.SelectRows( " +

                    // Gets name of last step (after "in" keyword)
                    _MExpression.Split("\nin")[1].TrimStart() +

                    // Adds 'each' keyword
                    @", each " +

                    // Bases incremental refresh on current column name
                    _ColumnName +

                    // Greater than or equal to RangeStart
                    @" >= Date.From ( #""RangeStart"" ) and " +

                    // and
                    _ColumnName +

                    // Less than RangeEnd
                    @" < Date.From ( #""RangeEnd"" ) )" +

                    // re-add 'in' keyword
                    "\nin\n" +

                    // Reference final step just added
                    @"    #""Incremental Refresh""";
            }

            // Success message for Refresh Policy configuration
            Info ( 
                "Successfully configured the Incremental Refresh policy.\n" + 
                "\nSelect the table and right-click on 'Apply Refresh Policy...'" + 
                "\nSelect & peform a 'Full Refresh' of all new policy partitons that are created." 
            );
            }
        else if (result == DialogResult.Cancel)
        {
            // if the user clicks the Cancel button, close the form and exit the script
            form.Close();
            Error ( "Cancelled configuration! Ending script without changes." );
            return;
        }
    }
    catch
    {
        Error( "No valid column selected! Ending script without changes." );
    }

}
catch
{
    Error( "No valid table selected! Ending script without changes." );
}

// To use this C# Script:
//
// 1. Run the script
// 2. Select the column that has the earliest date
// 3. Select the column that has the latest date

// List of all DateTime columns in the model
var _dateColumns = Model.AllColumns.Where(c => c.DataType == DataType.DateTime ).ToList();

// Select the column with the earliest date in the model
try
{
    string _EarliestDate = 
        SelectColumn(
            _dateColumns, 
            null, 
            "Select the Column with the Earliest Date:"
        ).DaxObjectFullName;

    try
    {
        // Select the column with the latest date in the model
        string _LatestDate = 
            SelectColumn(
                _dateColumns, 
                null, 
                "Select the Column with the Latest Date:"
            ).DaxObjectFullName;


        // Create measure for reference date
        var _RefDateMeasure = _dateColumns[0].Table.AddMeasure(
            "RefDate",
            "CALCULATE ( MAX ( " + _LatestDate + " ), REMOVEFILTERS ( ) )"
        );


        // Formatted date table DAX
        // Based on date table from https://www.sqlbi.com/topics/date-table/
        // To adjust, copy everything after the @" into a DAX query window & replace

        var _DateDaxExpression = @"-- Reference date for the latest date in the report
        -- Until when the business wants to see data in reports
        VAR _Refdate_Measure = [RefDate]
        VAR _Today = TODAY ( )

        -- Replace with ""Today"" if [RefDate] evaluates blank
        VAR _Refdate = IF ( ISBLANK ( _Refdate_Measure ), _Today, _Refdate_Measure )
            VAR _RefYear        = YEAR ( _Refdate )
            VAR _RefQuarter     = _RefYear * 100 + QUARTER(_Refdate)
            VAR _RefMonth       = _RefYear * 100 + MONTH(_Refdate)
            VAR _RefWeek_EU     = _RefYear * 100 + WEEKNUM(_Refdate, 2)

        -- Earliest date in the model scope
        VAR _EarliestDate       = DATE ( YEAR ( MIN ( " + _EarliestDate + @" ) ) - 2, 1, 1 )
        VAR _EarliestDate_Safe  = MIN ( _EarliestDate, DATE ( YEAR ( _Today ) + 1, 1, 1 ) )

        -- Latest date in the model scope
        VAR _LatestDate_Safe    = DATE ( YEAR ( _Refdate ) + 2, 12, 1 )

        ------------------------------------------
        -- Base calendar table
        VAR _Base_Calendar      = CALENDAR ( _EarliestDate_Safe, _LatestDate_Safe )
        ------------------------------------------



        ------------------------------------------
        VAR _IntermediateResult = 
            ADDCOLUMNS ( _Base_Calendar,

                    ------------------------------------------
                ""Calendar Year Number (ie 2021)"",           --|
                    YEAR ([Date]),                          --|-- Year
                                                            --|
                ""Calendar Year (ie 2021)"",                  --|
                    FORMAT ([Date], ""YYYY""),                --|
                    ------------------------------------------

                    ------------------------------------------
                ""Calendar Quarter Year (ie Q1 2021)"",       --|
                    ""Q"" &                                   --|-- Quarter
                    CONVERT(QUARTER([Date]), STRING) &      --|
                    "" "" &                                   --|
                    CONVERT(YEAR([Date]), STRING),          --|
                                                            --|
                ""Calendar Year Quarter (ie 202101)"",        --|
                    YEAR([Date]) * 100 + QUARTER([Date]),   --|
                    ------------------------------------------

                    ------------------------------------------
                ""Calendar Month Year (ie Jan 21)"",          --|
                    FORMAT ( [Date], ""MMM YY"" ),            --|-- Month
                                                            --|
                ""Calendar Year Month (ie 202101)"",          --|
                    YEAR([Date]) * 100 + MONTH([Date]),     --|
                                                            --|
                ""Calendar Month (ie Jan)"",                  --|
                    FORMAT ( [Date], ""MMM"" ),               --|
                                                            --|
                ""Calendar Month # (ie 1)"",                  --|
                    MONTH ( [Date] ),                       --|
                    ------------------------------------------

                    ------------------------------------------
                ""Calendar Week EU (ie WK25)"",               --|
                    ""WK"" & WEEKNUM( [Date], 2 ),            --|-- Week
                                                            --|
                ""Calendar Week Number EU (ie 25)"",          --|
                    WEEKNUM( [Date], 2 ),                   --|
                                                            --|
                ""Calendar Year Week Number EU (ie 202125)"", --|
                    YEAR ( [Date] ) * 100                   --|
                    +                                       --|
                    WEEKNUM( [Date], 2 ),                   --|
                                                            --|
                ""Calendar Week US (ie WK25)"",               --|
                    ""WK"" & WEEKNUM( [Date], 1 ),            --|
                                                            --|
                ""Calendar Week Number US (ie 25)"",          --|
                    WEEKNUM( [Date], 1 ),                   --|
                                                            --|
                ""Calendar Year Week Number US (ie 202125)"", --|
                    YEAR ( [Date] ) * 100                   --|
                    +                                       --|
                    WEEKNUM( [Date], 1 ),                   --|
                                                            --|
                ""Calendar Week ISO (ie WK25)"",              --|
                    ""WK"" & WEEKNUM( [Date], 21 ),           --|
                                                            --|
                ""Calendar Week Number ISO (ie 25)"",         --|
                    WEEKNUM( [Date], 21 ),                  --|
                                                            --|
                ""Calendar Year Week Number ISO (ie 202125)"",--|
                    YEAR ( [Date] ) * 100                   --|
                    +                                       --|
                    WEEKNUM( [Date], 21 ),                  --|
                    ------------------------------------------

                    ------------------------------------------
                ""Weekday Short (i.e. Mon)"",                 --|
                    FORMAT ( [Date], ""DDD"" ),               --|-- Weekday
                                                            --|
                ""Weekday Name (i.e. Monday)"",               --|
                    FORMAT ( [Date], ""DDDD"" ),              --|
                                                            --|
                ""Weekday Number EU (i.e. 1)"",               --|
                    WEEKDAY ( [Date], 2 ),                  --|
                    ------------------------------------------

                    ------------------------------------------
                ""Calendar Month Day (i.e. Jan 05)"",         --|
                    FORMAT ( [Date], ""MMM DD"" ),            --|-- Day
                                                            --|
                ""Calendar Month Day (i.e. 0105)"",           --|
                    MONTH([Date]) * 100                     --|
                    +                                       --|
                    DAY([Date]),                            --|
                                                            --|
                ""YYYYMMDD"",                                 --|
                    YEAR ( [Date] ) * 10000                 --|
                    +                                       --|
                    MONTH ( [Date] ) * 100                  --|
                    +                                       --|
                    DAY ( [Date] ),                         --|
                    ------------------------------------------


                    ------------------------------------------
                ""IsDateInScope"",                            --|
                    [Date] <= _Refdate                      --|-- Boolean
                    &&                                      --|
                    YEAR([Date]) > YEAR(_EarliestDate),     --|
                                                            --|
                ""IsBeforeThisMonth"",                        --|
                    [Date] <= EOMONTH ( _Refdate, -1 ),     --|
                                                            --|
                ""IsLastMonth"",                              --|
                    [Date] <= EOMONTH ( _Refdate, 0 )       --|
                    &&                                      --|
                    [Date] > EOMONTH ( _Refdate, -1 ),      --|
                                                            --|
                ""IsYTD"",                                    --|
                    MONTH([Date])                           --|
                    <=                                      --|
                    MONTH(EOMONTH ( _Refdate, 0 )),         --|
                                                            --|
                ""IsActualToday"",                            --|
                    [Date] = _Today,                        --|
                                                            --|
                ""IsRefDate"",                                --|
                    [Date] = _Refdate,                      --|
                                                            --|
                ""IsHoliday"",                                --|
                    MONTH([Date]) * 100                     --|
                    +                                       --|
                    DAY([Date])                             --|
                        IN {0101, 0501, 1111, 1225},        --|
                                                            --|
                ""IsWeekday"",                                --|
                    WEEKDAY([Date], 2)                      --|
                        IN {1, 2, 3, 4, 5})                 --|
                    ------------------------------------------

        VAR _Result = 

                    --------------------------------------------
            ADDCOLUMNS (                                      --|
                _IntermediateResult,                          --|-- Boolean #2
                ""IsThisYear"",                                 --|
                    [Calendar Year Number (ie 2021)]          --|
                        = _RefYear,                           --|
                                                            --|
                ""IsThisMonth"",                                --|
                    [Calendar Year Month (ie 202101)]         --|
                        = _RefMonth,                          --|
                                                            --|
                ""IsThisQuarter"",                              --|
                    [Calendar Year Quarter (ie 202101)]       --|
                        = _RefQuarter,                        --|
                                                            --|
                ""IsThisWeek"",                                 --|
                    [Calendar Year Week Number EU (ie 202125)]--|
                        = _RefWeek_EU                         --|
            )                                                 --|
                    --------------------------------------------

        RETURN 
            _Result";

        // Create date table
        var _date = Model.AddCalculatedTable(
            "Date",
            _DateDaxExpression
        );

        //-------------------------------------------------------------------------------------------//

        // Sort by...

        // Sort Weekdays
        (_date.Columns["Weekday Name (i.e. Monday)"] as CalculatedTableColumn).SortByColumn = (_date.Columns["Weekday Number EU (i.e. 1)"] as CalculatedTableColumn);
        (_date.Columns["Weekday Short (i.e. Mon)"] as CalculatedTableColumn).SortByColumn = (_date.Columns["Weekday Number EU (i.e. 1)"] as CalculatedTableColumn);

        // Sort Weeks
        (_date.Columns["Calendar Week EU (ie WK25)"] as CalculatedTableColumn).SortByColumn = (_date.Columns["Calendar Week Number EU (ie 25)"] as CalculatedTableColumn);
        (_date.Columns["Calendar Week ISO (ie WK25)"] as CalculatedTableColumn).SortByColumn = (_date.Columns["Calendar Week Number ISO (ie 25)"] as CalculatedTableColumn);
        (_date.Columns["Calendar Week US (ie WK25)"] as CalculatedTableColumn).SortByColumn = (_date.Columns["Calendar Week Number US (ie 25)"] as CalculatedTableColumn);

        // Sort Months
        (_date.Columns["Calendar Month (ie Jan)"] as CalculatedTableColumn).SortByColumn = (_date.Columns["Calendar Month # (ie 1)"] as CalculatedTableColumn);
        (_date.Columns["Calendar Month Day (i.e. Jan 05)"] as CalculatedTableColumn).SortByColumn = (_date.Columns["Calendar Month Day (i.e. 0105)"] as CalculatedTableColumn);
        (_date.Columns["Calendar Month Year (ie Jan 21)"] as CalculatedTableColumn).SortByColumn = (_date.Columns["Calendar Year Month (ie 202101)"] as CalculatedTableColumn);

        // Sort Quarters
        (_date.Columns["Calendar Quarter Year (ie Q1 2021)"] as CalculatedTableColumn).SortByColumn = (_date.Columns["Calendar Year Quarter (ie 202101)"] as CalculatedTableColumn);

        // Sort Years
        (_date.Columns["Calendar Year (ie 2021)"] as CalculatedTableColumn).SortByColumn = (_date.Columns["Calendar Year Number (ie 2021)"] as CalculatedTableColumn);


        //-------------------------------------------------------------------------------------------//


        // For all the columns in the date table:
        foreach (var c in _date.Columns )
        {
        c.DisplayFolder = "7. Boolean Fields";
        c.IsHidden = true;

        // Organize the date table into folders
            if ( ( c.DataType == DataType.DateTime & c.Name.Contains("Date") ) )
                {
                c.DisplayFolder = "6. Calendar Date";
                c.IsHidden = false;
                c.IsKey = true;
                }

            if ( c.Name == "YYMMDDDD" )
                {
                c.DisplayFolder = "6. Calendar Date";
                c.IsHidden = true;
                }

            if ( c.Name.Contains("Year") & c.DataType != DataType.Boolean )
                {
                c.DisplayFolder = "1. Year";
                c.IsHidden = false;
                }

            if ( c.Name.Contains("Week") & c.DataType != DataType.Boolean )
                {
                c.DisplayFolder = "4. Week";
                c.IsHidden = true;
                }

            if ( c.Name.Contains("day") & c.DataType != DataType.Boolean )
                {
                c.DisplayFolder = "5. Weekday / Workday\\Weekday";
                c.IsHidden = false;
                }

            if ( c.Name.Contains("Month") & c.DataType != DataType.Boolean )
                {
                c.DisplayFolder = "3. Month";
                c.IsHidden = false;
                }

            if ( c.Name.Contains("Quarter") & c.DataType != DataType.Boolean )
                {
                c.DisplayFolder = "2. Quarter";
                c.IsHidden = false;
                }

        }

        // Mark as date table
        _date.DataCategory = "Time";


        //-------------------------------------------------------------------------------------------//


        // Create Workdays MTD, QTD, YTD logic 
        //      (separate into measures & calc. column to be easier to maintain)
        //
        // Add calculated columns for Workdays MTD, QTD, YTD

        string _WorkdaysDax = @"VAR _Holidays =
            CALCULATETABLE (
                DISTINCT ('Date'[Date]),
                'Date'[IsHoliday] <> TRUE
            )
        VAR _WeekdayName = CALCULATE ( SELECTEDVALUE ( 'Date'[Weekday Short (i.e. Mon)] ) )
        VAR _WeekendDays = SWITCH (
                _WeekdayName,
                ""Sat"", 2,
                ""Sun"", 3,
                0
            )
        VAR _WorkdaysMTD =
            CALCULATE (
                NETWORKDAYS (
                    CALCULATE (
                        MIN ('Date'[Date]),
                        ALLEXCEPT ('Date', 'Date'[Calendar Month Year (ie Jan 21)])
                    ),
                    CALCULATE (MAX ('Date'[Date]) - _WeekendDays),
                    1,
                    _Holidays
                )
            )
                + 1
        RETURN
            IF (_WorkdaysMTD < 1, 1, _WorkdaysMTD)";

        _date.AddCalculatedColumn(
            "Workdays MTD",
            _WorkdaysDax,
            "5. Weekday / Workday\\Workdays"
        );

        _date.AddCalculatedColumn(
            "Workdays QTD",
            _WorkdaysDax.Replace("'Date'[Calendar Month Year (ie Jan 21)]", "'Date'[Calendar Quarter Year (ie Q1 2021)]"),
            "5. Weekday / Workday\\Workdays"
        );

        _date.AddCalculatedColumn(
            "Workdays YTD",
            _WorkdaysDax.Replace("'Date'[Calendar Month Year (ie Jan 21)]", "'Date'[Calendar Year (ie 2021)]"),
            "5. Weekday / Workday\\Workdays"
        );


        //-------------------------------------------------------------------------------------------//


        // Create measures for showing how many workdays passed
        _WorkdaysDax = @"CALCULATE(
            MAX( 'Date'[Workdays MTD] ),
            'Date'[IsDateInScope] = TRUE
        )";

        _date.AddMeasure(
            "# Workdays MTD",
            _WorkdaysDax,
            "5. Weekday / Workday\\Measures\\# Workdays"
        );

        _date.AddMeasure(
            "# Workdays QTD",
            _WorkdaysDax.Replace("MTD", "QTD"),
            "5. Weekday / Workday\\Measures\\# Workdays"
        );

        _date.AddMeasure(
            "# Workdays YTD",
            _WorkdaysDax.Replace("MTD", "YTD"),
            "5. Weekday / Workday\\Measures\\# Workdays"
        );

        // Create measures showing how many workdays are in the selected period

        _WorkdaysDax = @"IF (
            HASONEVALUE ('Date'[Calendar Month Year (ie Jan 21)]),
            CALCULATE (
                MAX ('Date'[Workdays MTD]),
                VALUES ('Date'[Calendar Month Year (ie Jan 21)])
            )
        )";

        _date.AddMeasure(
            "# Workdays in Selected Month",
            _WorkdaysDax,
            "5. Weekday / Workday\\Measures\\# Workdays"
        );

        _date.AddMeasure(
            "# Workdays in Selected Quarter",
            _WorkdaysDax.Replace("MTD", "QTD").Replace("'Date'[Calendar Month Year (ie Jan 21)]", "'Date'[Calendar Quarter Year (ie Q1 2021)]"),
            "5. Weekday / Workday\\Measures\\# Workdays"
        );

        _date.AddMeasure(
            "# Workdays in Selected Year",
            _WorkdaysDax.Replace("MTD", "YTD").Replace("'Date'[Calendar Month Year (ie Jan 21)]", "'Date'[Calendar Year (ie 2021)]"),
            "5. Weekday / Workday\\Measures\\# Workdays"
        );


        // Create measures showing how many workdays passed as a %

        _WorkdaysDax = @"IF (
            HASONEVALUE ('Date'[Calendar Month Year (ie Jan 21)]),
            MROUND (
                DIVIDE ([# Workdays MTD], [# Workdays in Selected Month]),
                0.01
            )
        )";

        _date.AddMeasure(
            "% Workdays MTD",
            _WorkdaysDax,
            "5. Weekday / Workday\\Measures\\# Workdays"
        );

        _date.AddMeasure(
            "% Workdays QTD",
            _WorkdaysDax.Replace("MTD", "QTD").Replace("'Date'[Calendar Month Year (ie Jan 21)]", "'Date'[Calendar Quarter Year (ie Q1 2021)]").Replace("Month", "Quarter"),
            "5. Weekday / Workday\\Measures\\# Workdays"
        );

        _date.AddMeasure(
            "% Workdays YTD",
            _WorkdaysDax.Replace("MTD", "YTD").Replace("'Date'[Calendar Month Year (ie Jan 21)]", "'Date'[Calendar Year (ie 2021)]").Replace("Month", "Year"),
            "5. Weekday / Workday\\Measures\\# Workdays"
        );


        //-------------------------------------------------------------------------------------------//


        // Move the reference measure to the newly created 'Date' table.
        _RefDateMeasure.Delete();
        _RefDateMeasure = Model.Tables["Date"].AddMeasure(
            "RefDate",
            "CALCULATE ( MAX ( " + _LatestDate + " ), REMOVEFILTERS ( ) )",
            "0. Measures"
        );

        _RefDateMeasure.IsHidden = true;

        Info ( "Created a new, organized 'Date' table based on the template in the C# Script.\nThe Earliest Date is taken from " + _EarliestDate + "\nThe Latest Date is taken from " + _LatestDate );

        }
        catch
        {
            Error( "Latest column not selected! Ending script without making changes." );
        }
}
catch
{
    Error( "Earliest column not selected! Ending script without making changes." );
}

// This script creates a new M Parameter as a 'Shared Expression'.
// It will also find the default value in all M partitions and replace them with the parameter object name.
//#r "System.Drawing"

using System.Drawing;
using System.Text.RegularExpressions;
using System.Windows.Forms;

// Hide the 'Running Macro' spinbox
ScriptHelper.WaitFormVisible = false;

// Initialize variables
string _ParameterName = "New Parameter";
string _ParameterValue = "ParameterValue";

// WinForms prompt to get Parameter Name / Value input
using (Form prompt = new Form())
{
    Font formFont = new Font("Segoe UI", 11); 

    // Prompt config
    prompt.AutoSize = true;
    prompt.MinimumSize = new Size(380, 120);
    prompt.Text = "Create New M Parameter";
    prompt.StartPosition = FormStartPosition.CenterScreen;

    // Find: label
    Label parameterNameLabel = new Label() { Text = "Enter Name:" };
    parameterNameLabel.Location = new Point(20, 20);
    parameterNameLabel.AutoSize = true;
    parameterNameLabel.Font = formFont;

    // Textbox for inputing the substring text
    TextBox parameterNameBox = new TextBox();
    parameterNameBox.Width = 200;
    parameterNameBox.Location = new Point(parameterNameLabel.Location.X + parameterNameLabel.Width + 20, parameterNameLabel.Location.Y - 4);
    parameterNameBox.SelectedText = "New Parameter";
    parameterNameBox.Font = formFont;

    // Replace: label
    Label parameterValueLabel = new Label() { Text = "Enter Value:" };
    parameterValueLabel.Location = new Point(parameterNameLabel.Location.X, parameterNameLabel.Location.Y + parameterNameLabel.Height + 20);
    parameterValueLabel.AutoSize = true;
    parameterValueLabel.Font = formFont;

    // Textbox for inputting the substring text
    TextBox parameterValueBox = new TextBox() { Left = parameterValueLabel.Right + 20, Top = parameterValueLabel.Location.Y - 4, Width = parameterNameBox.Width };
    parameterValueBox.SelectedText = "Parameter Value";
    parameterValueBox.Font = formFont;

    // OK Button
    Button okButton = new Button() { Text = "Create", Left = 20, Width = 75, Top = parameterValueBox.Location.Y + parameterValueBox.Height + 20 };
    okButton.MinimumSize = new Size(75, 25);
    okButton.AutoSize = true;
    okButton.Font = formFont;

    // Cancel Button
    Button cancelButton = new Button() { Text = "Cancel", Left = okButton.Location.X + okButton.Width + 10, Top = okButton.Location.Y };
    cancelButton.MinimumSize = new Size(75, 25);
    cancelButton.AutoSize = true;
    cancelButton.Font = formFont;

    // Button actions
    okButton.Click += (sender, e) => { _ParameterName = parameterNameBox.Text; _ParameterValue = parameterValueBox.Text; prompt.DialogResult = DialogResult.OK; };
    cancelButton.Click += (sender, e) => { prompt.DialogResult = DialogResult.Cancel; };

    prompt.AcceptButton = okButton;
    prompt.CancelButton = cancelButton;

    prompt.Controls.Add(parameterNameLabel);
    prompt.Controls.Add(parameterNameBox);
    prompt.Controls.Add(parameterValueLabel);
    prompt.Controls.Add(parameterValueBox);
    prompt.Controls.Add(okButton);
    prompt.Controls.Add(cancelButton);

    // The user clicked OK, so perform the find-and-replace logic
    if (prompt.ShowDialog() == DialogResult.OK)
    {

        // Creates the parameter
        Model.AddExpression( 
            _ParameterName, 
            @"
        """ + _ParameterValue +
        @""" meta
        [
            IsParameterQuery = true,
            IsParameterQueryRequired = true,
            Type = type text
        ]"
        );


        // Informs the user that the parameter was successfully created
        Info ( 
            "Successfully created a new parameter: " + @"""" +
            _ParameterName + @"""" +
            "\nDefault value: " + @"""" +
            _ParameterValue + @"""");


        // Finds the parameter default value in M Partitions & replaces with the parameter name
        string _Find = @"""" + _ParameterValue + @"""";
        string _Replace = @"#""" + _ParameterName + @"""";

        int _NrMPartitions = 0;
        int _NrReplacements = 0;
        var _ReplacementsList = new List<string>();

        foreach ( var _Tables in Model.Tables )
        {
            foreach ( var _p in _Tables.Partitions )
            {
                if ( _p.SourceType == PartitionSourceType.M )
                {
                    if ( _p.Expression != _p.Expression.Replace( _Find, _Replace ) )
                    {
                        _p.Expression = _p.Expression.Replace( _Find, _Replace );

                        // Tracks which M partitions were replaced (and how many)
                        _NrReplacements = _NrReplacements + 1;
                        _ReplacementsList.Add( _p.Name );
                    }

                // Counts the total # M Partitions
                _NrMPartitions = _NrMPartitions + 1;
                }
            }
        }


        // Makes a bulleted list of all the M partitions that were replaced
        string _ReplacedPartitions = " • " + String.Join("\n • ", _ReplacementsList );


        // Informs 
        //      - Whether the Find & Replace was successful
        //      - How many M partitions were replaced
        //      - Which M partitions had the Find & Replace done
        Info (
            "Successfully replaced\n\n " +
            _Find + 
            "\n\n with: \n\n" + 
            _Replace + 
            "\n\n in " + 
            Convert.ToString(_NrReplacements) +
            " of " +
            Convert.ToString(_NrMPartitions) +  
            " M Partitions:\n" +
            _ReplacedPartitions
        );

    }
    else
    {
    Error ( "Cancelled input! Ended script without changes.");
    }
}

// Loop through all tables:
foreach(var table in Model.Tables)
{
    if (table is CalculationGroupTable)
    {
        table.TableGroup = "Calculation Groups";
    }
    else if (!table.UsedInRelationships.Any() && table.Measures.Any(m => m.IsVisible))
    {
        // Tables containing visible measures, but no relationships to other tables
        table.TableGroup = "Measure Groups";
    }
    else if (table.UsedInRelationships.All(r => r.FromTable == table) && table.UsedInRelationships.Any())
    {
        // Tables exclusively on the "many" side of relationships:
        table.TableGroup = "Facts";
    }
    else if (!table.UsedInRelationships.Any() && table is CalculatedTable && !table.Measures.Any())
    {
        // Tables without any relationships, that are Calculated Tables and do not have measures:
        table.TableGroup = "Parameter Tables";
    }
    else if (table.UsedInRelationships.Any(r => r.ToTable == table))
    {
        // Tables on the "one" side of relationships:
        table.TableGroup = "Dimensions";
    }
    else
    {
        // All other tables:
        table.TableGroup = "Misc";
    }
}

// Create a calculated table with a single column which is hidden:
var table = Model.AddCalculatedTable("Model Measures", "{0}");
table.Columns[0].IsHidden = true;

// Before running the script, select the measures or columns that you
// would like to use as field parameters (hold down CTRL to select multiple
// objects). Also, you may change the name of the field parameter table
// below. NOTE: If used against Power BI Desktop, you must enable unsupported
// features under File > Preferences (TE2) or Tools > Preferences (TE3).
var name = "H_AxisParameter";

if(Selected.Columns.Count == 0 && Selected.Measures.Count == 0) throw new Exception("No columns or measures selected!");

// Construct the DAX for the calculated table based on the current selection:
var objects = Selected.Columns.Any() ? Selected.Columns.Cast<ITabularTableObject>() : Selected.Measures;
var dax = "{\n    " + string.Join(",\n    ", objects.Select((c,i) => string.Format("(\"{0}\", NAMEOF('{1}'[{0}]), {2})", c.Name, c.Table.Name, i))) + "\n}";

// Add the calculated table to the model:
var table = Model.AddCalculatedTable(name, dax);

// In TE2 columns are not created automatically from a DAX expression, so 
// we will have to add them manually:
var te2 = table.Columns.Count == 0;
var nameColumn = te2 ? table.AddCalculatedTableColumn(name, "[Value1]") : table.Columns["Value1"] as CalculatedTableColumn;
var fieldColumn = te2 ? table.AddCalculatedTableColumn(name + " Fields", "[Value2]") : table.Columns["Value2"] as CalculatedTableColumn;
var orderColumn = te2 ? table.AddCalculatedTableColumn(name + " Order", "[Value3]") : table.Columns["Value3"] as CalculatedTableColumn;

