foreach (var originalMeasure in selectedMeasures)
{
    var baseMeasureName = originalMeasure.Name;
    var folderPath = $"TI\\{baseMeasureName}";

    // Helper Action to handle the "Overwrite or Create" logic with counting
    Action<string, string, string> AddOrUpdateMeasure = (name, expression, format) => {
        Measure m;
        bool exists = calculationsTable.Measures.Any(x => x.Name == name);

        if (exists) 
        {
            m = calculationsTable.Measures[name];
            m.Expression = expression;
            updatedCount++;
        } 
        else 
        {
            m = calculationsTable.AddMeasure(name, expression);
            createdCount++;
        }

        // Set properties
        m.DisplayFolder = folderPath;
        m.Description = $"TI of {baseMeasureName}";
        m.FormatString = format;

        allProcessedNames.Add(m.Name);
    };

    // ==== 1. Base Time Intelligence Measures ====
    AddOrUpdateMeasure($"{baseMeasureName} PD", $@"TI.CARD.PD([{baseMeasureName}])", "#,0.0");
    AddOrUpdateMeasure($"{baseMeasureName} PM", $@"TI.CARD.PM([{baseMeasureName}])", "#,0.0");
    AddOrUpdateMeasure($"{baseMeasureName} PY", $@"TI.CARD.PY([{baseMeasureName}])", "#,0.0");

    // ==== 2. MTD / YTD / YOY Measures ====
    AddOrUpdateMeasure($"{baseMeasureName} MTD", $@"TOTALMTD([{baseMeasureName}], D_Calendar[Calendar Date])", "#,0.0");
    AddOrUpdateMeasure($"{baseMeasureName} YTD", $@"TOTALYTD([{baseMeasureName}], D_Calendar[Calendar Date])", "#,0.0");

    AddOrUpdateMeasure($"{baseMeasureName} DoD", $@"TI.CARD.DIFF([{baseMeasureName}],[{baseMeasureName} PD])", "#,0.0");
    AddOrUpdateMeasure($"{baseMeasureName} DoD(%)", $@"TI.CARD.DIFF_PRC( [{baseMeasureName} DoD], [{baseMeasureName} PD] )", "#,0.0%;-#,0.0%;#,0.0%");

    AddOrUpdateMeasure($"{baseMeasureName} MoM", $@"TI.CARD.DIFF([{baseMeasureName}],[{baseMeasureName} PM])", "#,0.0");
    AddOrUpdateMeasure($"{baseMeasureName} MoM(%)", $@"TI.CARD.DIFF_PRC( [{baseMeasureName} MoM], [{baseMeasureName} PM] )", "#,0.0%;-#,0.0%;#,0.0%");

    AddOrUpdateMeasure($"{baseMeasureName} YoY", $@"TI.CARD.DIFF([{baseMeasureName}],[{baseMeasureName} PY])", "#,0.0");
    AddOrUpdateMeasure($"{baseMeasureName} YoY(%)", $@"TI.CARD.DIFF_PRC( [{baseMeasureName} YoY], [{baseMeasureName} PY] )", "#,0.0%;-#,0.0%;#,0.0%");

    //// ==== 3. Comparison Measure ====
    //string comparisonExpr = $@"SWITCH(
    //    TRUE( ),
    //    HASONEVALUE( D_Calendar[Calendar Date] ), [{baseMeasureName} PD],
    //    HASONEVALUE( D_Calendar[Month Short Name] ), [{baseMeasureName} PM],
    //    HASONEVALUE( D_Calendar[Year] ), [{baseMeasureName} PY],
    //    BLANK( )
    //)";
    //AddOrUpdateMeasure($"Comparison {baseMeasureName}", comparisonExpr, "#,0.0");

    string comparisonExpr = $@"SWITCH(
            SELECTEDVALUE(H_Comparison[Description]),
            ""vs PM"", [{baseMeasureName} PM],
            ""vs PY"", [{baseMeasureName} PY]
    )";
    AddOrUpdateMeasure($"Comparison {baseMeasureName}", comparisonExpr, "#,0.0");



    // ==== 4. Difference & Formatting Measures ====
    AddOrUpdateMeasure($"{baseMeasureName} vs Comparison Diff", $@"TI.CARD.DIFF([{baseMeasureName}],[Comparison {baseMeasureName}])", "#,0.0");
    AddOrUpdateMeasure($"{baseMeasureName} Color", $@"TI.CARD.COLOR([{baseMeasureName} vs Comparison Diff],FALSE)", "#,0.0");
    AddOrUpdateMeasure($"{baseMeasureName} vs Comparison Diff format", $@"TI.CARD.DIFF_FORMAT([Comparison {baseMeasureName}],[{baseMeasureName} vs Comparison Diff])", "#,0.0");
}

