{
    Error("Table 'Calculations' not found. Please ensure the table exists or update the script name.");
    return;
}

// Counters for the summary report
int createdCount = 0;
int updatedCount = 0;
var allProcessedNames = new List<string>();

foreach (var originalMeasure in selectedMeasures)
{
    var baseMeasureName = originalMeasure.Name;
    var folderPath = $"TI\\{baseMeasureName}";

    // Helper Action to handle the "Overwrite or Create" logic with counting
    Action<string, string, string> AddOrUpdateMeasure = (name, expression, format) => {
        Measure m;
        bool exists = calculationsTable.Measures.Any(x => x.Name == name);

        if (exists) 
        {
            m = calculationsTable.Measures[name];
            m.Expression = expression;
            updatedCount++;
        } 
        else 
        {
            m = calculationsTable.AddMeasure(name, expression);
            createdCount++;
        }

        // Set properties
        m.DisplayFolder = folderPath;
        m.Description = $"BDG of {baseMeasureName}";
        m.FormatString = format;

        allProcessedNames.Add(m.Name);
    };


    // ==== 4. Difference & Formatting Measures ====
    AddOrUpdateMeasure($"{baseMeasureName} vs BDG Diff", $@"TI.CARD.DIFF([{baseMeasureName}],[{baseMeasureName} BDG])", "#,0.0");
    AddOrUpdateMeasure($"{baseMeasureName} vs BDG Diff(%)", $@"TI.CARD.DIFF_PRC([{baseMeasureName} vs BDG Diff],[{baseMeasureName} BDG])", "#,0.0%;-#,0.0%;#,0.0%");
    AddOrUpdateMeasure($"{baseMeasureName} vs BDG Diff format", $@"TI.CARD.DIFF_FORMAT([{baseMeasureName} BDG],[{baseMeasureName} vs BDG Diff])", "#,0.0");
}

