if (!selectedMeasures.Any())
{
    Error("Please select one or more measures!");
    return;
}

var calculationsTable = Model.Tables["Calculations"];
var allNewMeasureNames = new List<string>();

foreach (var originalMeasure in selectedMeasures)
{
    var baseName = originalMeasure.Name;

    var formatNumber = "#,0";
    var formatPct = "#,0.0%;-#,0.0%;#,0.0%";

    var batchMeasures = new List<string>();

    // Helper function with overwrite logic + folder hierarchy
    Func<string, string, string, string, string> add =
        (suffix, expr, format, subFolder) =>
    {
        var name = $"{baseName} {suffix}";
        var folder = $"TI\\{baseName}\\{subFolder}";

        var existing = calculationsTable.Measures
            .FirstOrDefault(m => m.Name == name);

        if (existing != null)
        {
            existing.Expression = expr;
            existing.FormatString = format;
            existing.DisplayFolder = folder;
            existing.Description = $"TI of {baseName}";

            updatedMeasures.Add(name);
            batchMeasures.Add(name);
            return name;
        }

        var m = calculationsTable.AddMeasure(name, expr);
        m.DisplayFolder = folder;
        m.Description = $"TI of {baseName}";
        m.FormatString = format;

        createdMeasures.Add(name);
        batchMeasures.Add(name);
        return name;
    };

    // ==== Base TI ====
    add("PD", $@"Common.TI.CARD.PD([{baseName}])", formatNumber, "DoD");
    add("PM", $@"Common.TI.CARD.PM([{baseName}],FALSE())", formatNumber, "MoM");
    add("PY", $@"Common.TI.CARD.PY([{baseName}],FALSE())", formatNumber, "YoY");

    // ==== Aggregations ====
    add("MTD", $@"TOTALMTD([{baseName}], mv_d_date[Date])", formatNumber, "MoM");
    add("YTD", $@"TOTALYTD([{baseName}], mv_d_date[Date])", formatNumber, "YoY");

    // ==== DoD ====
    add("DoD", $@"Common.TI.CARD.DIFF([{baseName}],[{baseName} PD])", formatNumber, "DoD");
    add("DoD(%)", $@"Common.TI.CARD.DIFF_PRC([{baseName} DoD],[{baseName} PD])", formatPct, "DoD");

    // ==== MoM ====
    add("MoM", $@"Common.TI.CARD.DIFF([{baseName}],[{baseName} PM])", formatNumber, "MoM");
    add("MoM(%)", $@"Common.TI.CARD.DIFF_PRC([{baseName} MoM],[{baseName} PM])", formatPct, "MoM");
    add("MoM(%) format", $@"Common.TI.CARD.DIFF_FORMAT([{baseName} PM],[{baseName} MoM])", formatNumber, "MoM");
    add("MoM Color", $@"Common.TI.CARD.COLOR([{baseName} MoM],FALSE)", formatNumber, "MoM");

    // ==== YoY ====
    add("YoY", $@"Common.TI.CARD.DIFF([{baseName}],[{baseName} PY])", formatNumber, "YoY");
    add("YoY(%)", $@"Common.TI.CARD.DIFF_PRC([{baseName} YoY],[{baseName} PY])", formatPct, "YoY");
    add("YoY(%) format", $@"Common.TI.CARD.DIFF_FORMAT([{baseName} PY],[{baseName} YoY])", formatNumber, "YoY");
    add("YoY Color", $@"Common.TI.CARD.COLOR([{baseName} YoY],FALSE)", formatNumber, "YoY");

//    // ==== Comparison ====
//    add("Comparison",
